<?php
declare(strict_types=1);
require dirname(__DIR__).'/src/EmployerContracts.php';
$n=0;function checkE(string $label,bool $ok):void{global $n;if(!$ok){fwrite(STDERR,"FAIL $label\n");exit(1);}echo "PASS $label\n";$n++;}
function rejectsE(callable $fn):bool{try{$fn();return false;}catch(Throwable){return true;}}
$now=strtotime('2026-11-23T00:00:00Z');
$org=['id'=>'org_demo1','approved'=>true,'email_verified'=>true,'domain_verified'=>true,'suspended'=>false,'verified_domains'=>['example.com']];
$create=['external_id'=>'ats-job-42','title'=>'Technical Support Specialist','description'=>'Provide support to customers, document requests and resolve technical issues with care.','employment_type'=>'full_time','work_mode'=>'remote','work_country'=>null,'location_text'=>'Remote: India','candidate_eligible_countries'=>['IN'],'apply_url'=>'https://careers.example.com/jobs/42','valid_through'=>'2026-12-15T23:00:00Z','consent_to_publish'=>true];
$validated=EmployerContracts::validateCreate($create,$org,$now,'terms-v1');
checkE('Approved employer identity required',EmployerContracts::permittedForPilot($org));
checkE('New owned job always pending review',$validated['status']==='pending_review');
checkE('Direct posting origin is not third-party source',$validated['origin_type']==='direct_employer');
checkE('Owned job has server-controlled org ID',$validated['owner_org_id']==='org_demo1');
checkE('Server consent includes terms version and time',$validated['consent_terms_version']==='terms-v1'&&$validated['consent_at']==='2026-11-23T00:00:00Z');
checkE('No redistribution by default',$validated['distribution_consent']===false);
checkE('No sponsorship inferred',$validated['visa_sponsorship']==='unknown');
checkE('No hiring country inferred for remote job',$validated['work_country']===null);
checkE('Unverified org blocked',rejectsE(fn()=>EmployerContracts::validateCreate($create,[...$org,'domain_verified'=>false],$now,'terms-v1')));
checkE('Suspended org blocked',rejectsE(fn()=>EmployerContracts::validateCreate($create,[...$org,'suspended'=>true],$now,'terms-v1')));
checkE('Unverified email blocked',rejectsE(fn()=>EmployerContracts::validateCreate($create,[...$org,'email_verified'=>false],$now,'terms-v1')));
checkE('Self-approval field blocked',rejectsE(fn()=>EmployerContracts::validateCreate([...$create,'approved'=>true],$org,$now,'terms-v1')));
checkE('Self-assign tenant blocked',rejectsE(fn()=>EmployerContracts::validateCreate([...$create,'owner_org_id'=>'org_other'], $org,$now,'terms-v1')));
checkE('Self-publish blocked',rejectsE(fn()=>EmployerContracts::validateCreate([...$create,'status'=>'published'], $org,$now,'terms-v1')));
checkE('Publication consent cannot be false',rejectsE(fn()=>EmployerContracts::validateCreate([...$create,'consent_to_publish'=>false],$org,$now,'terms-v1')));
checkE('Host outside employer domain rejected',rejectsE(fn()=>EmployerContracts::validateCreate([...$create,'apply_url'=>'https://elsewhere.com/job'], $org,$now,'terms-v1')));
checkE('Host suffix impersonation rejected',rejectsE(fn()=>EmployerContracts::validateCreate([...$create,'apply_url'=>'https://example.com.evil.net/job'], $org,$now,'terms-v1')));
checkE('Unsafe HTTP link rejected',rejectsE(fn()=>EmployerContracts::validateCreate([...$create,'apply_url'=>'http://example.com/job'], $org,$now,'terms-v1')));
checkE('Onsite requires physical country',rejectsE(fn()=>EmployerContracts::validateCreate([...$create,'work_mode'=>'onsite'], $org,$now,'terms-v1')));
checkE('Hybrid requires physical country',rejectsE(fn()=>EmployerContracts::validateCreate([...$create,'work_mode'=>'hybrid'], $org,$now,'terms-v1')));
checkE('Onsite with ISO country accepted',EmployerContracts::validateCreate([...$create,'work_mode'=>'onsite','work_country'=>'DE'],$org,$now,'terms-v1')['work_country']==='DE');
checkE('Invalid country not accepted',rejectsE(fn()=>EmployerContracts::validateCreate([...$create,'work_country'=>'ZZ'],$org,$now,'terms-v1')));
checkE('Unknown applicant countries not treated as worldwide',EmployerContracts::validateCreate([...$create,'candidate_eligible_countries'=>[]],$org,$now,'terms-v1')['candidate_eligible_countries']===[]);
checkE('Duplicate country codes rejected',rejectsE(fn()=>EmployerContracts::validateCreate([...$create,'candidate_eligible_countries'=>['IN','IN']],$org,$now,'terms-v1')));
checkE('Invalid eligibility country rejected',rejectsE(fn()=>EmployerContracts::validateCreate([...$create,'candidate_eligible_countries'=>['ZZ']],$org,$now,'terms-v1')));
checkE('Premature expiry rejected',rejectsE(fn()=>EmployerContracts::validateCreate([...$create,'valid_through'=>'2026-11-23T12:00:00Z'],$org,$now,'terms-v1')));
checkE('Impossible 31 November cannot become December expiry',rejectsE(fn()=>EmployerContracts::validateCreate([...$create,'valid_through'=>'2026-11-31T12:00:00Z'],$org,$now,'terms-v1')));
checkE('Impossible February leap day rejected',rejectsE(fn()=>EmployerContracts::validateCreate([...$create,'valid_through'=>'2026-02-30T00:00:00Z'],$org,$now,'terms-v1')));
checkE('Explicit real RFC3339 offset expiry retained as UTC',EmployerContracts::validateCreate([...$create,'valid_through'=>'2026-12-15T23:00:00+05:30'],$org,$now,'terms-v1')['valid_through']==='2026-12-15T17:30:00Z');
checkE('Long-lived vacancy renewal blocked',rejectsE(fn()=>EmployerContracts::validateCreate([...$create,'valid_through'=>'2027-06-20T00:00:00Z'],$org,$now,'terms-v1')));
checkE('Salary minimum greater than maximum rejected',rejectsE(fn()=>EmployerContracts::validateCreate([...$create,'salary_min'=>200,'salary_max'=>100,'salary_currency'=>'USD','salary_period'=>'year'],$org,$now,'terms-v1')));
checkE('Salary requires disclosed currency/period',rejectsE(fn()=>EmployerContracts::validateCreate([...$create,'salary_min'=>50000],$org,$now,'terms-v1')));
checkE('String sponsorship enum not boolean',rejectsE(fn()=>EmployerContracts::validateCreate([...$create,'visa_sponsorship'=>true],$org,$now,'terms-v1')));
checkE('Payment or passport field mass assignment blocked',rejectsE(fn()=>EmployerContracts::validateCreate([...$create,'passport_upload'=>'required'],$org,$now,'terms-v1')));
checkE('Candidate personal documents not in record',!array_key_exists('applicant_data',$validated));
checkE('Wrong tenant cannot modify job',rejectsE(fn()=>EmployerContracts::assertOwner($validated,[...$org,'id'=>'org_diff1'])));
checkE('Provider imports cannot be queried as owned jobs',EmployerContracts::visibleForPartner([$validated,['origin_type'=>'provider','owner_org_id'=>'org_demo1']],$org)===[$validated]);
checkE('Read-side rejects unapproved org',rejectsE(fn()=>EmployerContracts::visibleForPartner([$validated],[...$org,'approved'=>false])));
checkE('Material editing returns to review',(EmployerContracts::validatePatch($validated,['title'=>'Senior Technical Support Specialist'],$org,$now,'terms-v1',1)['status']==='pending_review'));
checkE('Material editing increments revision',EmployerContracts::validatePatch($validated,['title'=>'Senior Technical Support Specialist'],$org,$now,'terms-v1',1)['revision']===2);
checkE('PATCH refuses an absent stored publication consent',rejectsE(fn()=>EmployerContracts::validatePatch(array_diff_key($validated,['publish_consent'=>true]),['title'=>'Senior Technical Support Specialist'],$org,$now,'terms-v1',1)));
checkE('PATCH refuses stored consent explicitly false',rejectsE(fn()=>EmployerContracts::validatePatch([...$validated,'publish_consent'=>false],['title'=>'Senior Technical Support Specialist'],$org,$now,'terms-v1',1)));
checkE('PATCH refuses missing consent terms evidence',rejectsE(fn()=>EmployerContracts::validatePatch(array_diff_key($validated,['consent_terms_version'=>true]),['title'=>'Senior Technical Support Specialist'],$org,$now,'terms-v1',1)));
checkE('PATCH refuses invalid or missing consent time evidence',rejectsE(fn()=>EmployerContracts::validatePatch([...$validated,'consent_at'=>'tomorrow'],['title'=>'Senior Technical Support Specialist'],$org,$now,'terms-v1',1)));
checkE('PATCH retains true recorded server-side consent timestamp',EmployerContracts::validatePatch($validated,['title'=>'Senior Technical Support Specialist'],$org,$now,'terms-v2',1)['consent_at']===$validated['consent_at']);
checkE('PATCH preserves original legal terms version, not new unconsented version',EmployerContracts::validatePatch($validated,['title'=>'Senior Technical Support Specialist'],$org,$now,'terms-v2',1)['consent_terms_version']===$validated['consent_terms_version']);
checkE('Stale If-Match rejected',rejectsE(fn()=>EmployerContracts::validatePatch($validated,['title'=>'New Technical Support Specialist'],$org,$now,'terms-v1',2)));
checkE('Patch cannot edit publication status',rejectsE(fn()=>EmployerContracts::validatePatch($validated,['status'=>'published'],$org,$now,'terms-v1',1)));
checkE('Patch cannot edit external_id',rejectsE(fn()=>EmployerContracts::validatePatch($validated,['external_id'=>'changed'],$org,$now,'terms-v1',1)));
checkE('PATCH validates rebuilt on-site job',rejectsE(fn()=>EmployerContracts::validatePatch($validated,['work_mode'=>'onsite'],$org,$now,'terms-v1',1)));
checkE('API idempotency key length validated',EmployerContracts::validateIdempotencyKey('request-0001')==='request-0001');
checkE('API rejects short idempotency key',rejectsE(fn()=>EmployerContracts::validateIdempotencyKey('a')));
$token=EmployerContracts::newOpaqueToken();
checkE('Opaque token has >=256 bits entropy',strlen($token)===64&&ctype_xdigit($token));
checkE('Token hash is keyed and not clear token',EmployerContracts::tokenFingerprint($token,str_repeat('B',40))!==$token);
checkE('Token fingerprint deterministic',EmployerContracts::tokenFingerprint($token,str_repeat('B',40))===EmployerContracts::tokenFingerprint($token,str_repeat('B',40)));
checkE('Token fingerprint rejects short server secret',rejectsE(fn()=>EmployerContracts::tokenFingerprint($token,'secret')));
echo "\n$n M12/M13/M14 gated domain contract checks passed.\n";
